async (page) => {
  const events = [];
  page.on('pageerror', e => events.push({t:'pageerror', m: e.message}));
  page.on('console', m => { if (m.type()==='error') events.push({t:'console', m: m.text()}); });
  await page.evaluate(() => {
    window.__ev = [];
    window.addEventListener('error', e => window.__ev.push('exception: ' + e.message));
    window.addEventListener('unhandledrejection', e => window.__ev.push('rejection: ' + (e.reason && e.reason.message || e.reason)));
  });
  const btns = await page.locator('button').all();
  const out = [];
  for (const b of btns) {
    const label = await b.evaluate(el => (el.closest('section,div')?.querySelector('h1,h2,h3')?.textContent || '') + ' | ' + el.textContent);
    events.length = 0;
    await page.evaluate(() => window.__ev.length = 0);
    await b.click();
    await page.waitForTimeout(2500);
    const ev = await page.evaluate(() => [...window.__ev]);
    out.push({label, ev, pw: [...events]});
  }
  return out;
}

